function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  for (const c of s) {
    const code = c.charCodeAt(0);
    if (code < 33 || code > 122 || c === '"' || c === '\\') return 'Characters must have ASCII codes 33 to 122, other than a double quote or backslash.';
  }
  return null;
}

