function reverseOnlyLetters(s) {
  const chars = s.split('');
  const isLetter = (c) => /[a-zA-Z]/.test(c);
  let left = 0;
  let right = chars.length - 1;
  while (left < right) {
    if (!isLetter(chars[left])) {
      left++;
    } else if (!isLetter(chars[right])) {
      right--;
    } else {
      [chars[left], chars[right]] = [chars[right], chars[left]];
      left++;
      right--;
    }
  }
  return chars.join('');
}

