function reverseOnlyLetters(s) {
  // Collect the letters, then refill the letter slots from the last letter backwards.
  const letters = [];
  for (const c of s) if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) letters.push(c);
  let out = '';
  for (const c of s) out += (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ? letters.pop() : c;
  return out;
}

