function generate(rand, size) {
  const allowed = [];
  for (let code = 33; code <= 122; code++) if (code !== 34 && code !== 92) allowed.push(String.fromCharCode(code));
  const letters = allowed.filter(c => /[a-zA-Z]/.test(c));
  const others = allowed.filter(c => !/[a-zA-Z]/.test(c));
  const length = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  // The share of letters varies from none to all.
  const mode = rand();
  const letterShare = mode < 0.15 ? 0 : mode < 0.3 ? 1 : rand();
  let s = '';
  for (let i = 0; i < length; i++) {
    const pool = rand() < letterShare ? letters : others;
    s += pool[Math.floor(rand() * pool.length)];
  }
  return [s];
}
